using System.ComponentModel.DataAnnotations;

namespace RepairCenter.Api.Models;

public sealed class ClientRequest { [Required, StringLength(150, MinimumLength=5)] public string FullName { get; set; } = string.Empty; [Required, StringLength(20, MinimumLength=7)] public string Phone { get; set; } = string.Empty; [Required, StringLength(250, MinimumLength=5)] public string Address { get; set; } = string.Empty; }
public sealed class EquipmentRequest { [Range(1,int.MaxValue)] public int ClientID { get; set; } [Range(1,int.MaxValue)] public int EquipmentModelID { get; set; } [Required, StringLength(100,MinimumLength=3)] public string SerialNumber { get; set; } = string.Empty; [StringLength(300)] public string? Notes { get; set; } }
public sealed class EmployeeRequest { [Required,StringLength(150,MinimumLength=5)] public string FullName { get; set; } = string.Empty; [Required,StringLength(20,MinimumLength=7)] public string Phone { get; set; } = string.Empty; public bool IsActive { get; set; } = true; public List<int> SpecializationIDs { get; set; } = new(); }
public sealed class CreateOrderRequest { [Range(1,int.MaxValue)] public int EquipmentID { get; set; } public DateTime AcceptedAt { get; set; } = DateTime.Today; public DateTime? IssuedAt { get; set; } [Required,StringLength(1000,MinimumLength=5)] public string FaultDescription { get; set; } = string.Empty; [Range(typeof(decimal),"0","99999999.99")] public decimal RepairCost { get; set; } [Range(1,int.MaxValue)] public int OrderStatusID { get; set; } public int? EmployeeID { get; set; } }
public sealed class UpdateOrderRequest { [Required,StringLength(1000,MinimumLength=5)] public string FaultDescription { get; set; } = string.Empty; [Range(typeof(decimal),"0","99999999.99")] public decimal RepairCost { get; set; } [Range(1,int.MaxValue)] public int OrderStatusID { get; set; } public DateTime? IssuedAt { get; set; } public int? EmployeeID { get; set; } public string? ChangeNote { get; set; } }
